create table tbl_auditorium (id bigint generated by default as identity, end_time time(0), is_external_public boolean not null, is_necessary_coffee boolean not null, is_necessary_screen boolean not null, is_necessary_sound_system boolean not null, num_people integer not null, "reservation_date" date not null, start_time time(0), time_open_auditory time(0), date_analysis timestamp(6), date_create timestamp(6) not null, reservation_type varchar(30) not null check ((reservation_type in ('FLEET_VEHICLE','AUDITORIUM','MEETING_ROOM'))), status varchar(30) not null check ((status in ('ENVIADA_PARA_ANALISE','APROVADA','REPROVADA','CANCELADA','EM_ATENDIMENTO','FINALIZADA'))), observation varchar(1000), reason varchar(255) not null, reason_failure varchar(255), user_name_approver varchar(255), user_name_requester varchar(255) not null, primary key (id));
create table tbl_driver (id bigint generated by default as identity, img varchar(255), name varchar(255) not null, primary key (id));
create table tbl_fleet_vehicles (id bigint generated by default as identity, exit_time time(0) not null, is_necessary_return boolean not null, is_necessary_van boolean not null, quantity_passengers integer not null, reservation_date date not null, return_time time(0), date_analysis timestamp(6), date_create timestamp(6) not null, id_driver bigint, reservation_type varchar(30) not null check ((reservation_type in ('FLEET_VEHICLE','AUDITORIUM','MEETING_ROOM'))), status varchar(30) not null check ((status in ('ENVIADA_PARA_ANALISE','APROVADA','REPROVADA','CANCELADA','EM_ATENDIMENTO','FINALIZADA'))), type_vehicle varchar(30) not null check ((type_vehicle in ('VAN','CARRO'))), contact varchar(50) not null, user_name_approver varchar(255), user_name_requester varchar(255) not null, departure_address varchar(255) not null, departure_address_return varchar(255), destination_address varchar(255) not null, destination_address_return varchar(255), reason varchar(255) not null, reason_failure varchar(255), reason_use_van varchar(255), primary key (id));
create table tbl_meeting_room (id bigint generated by default as identity, end_time time(0) not null, is_coffee boolean not null, num_people integer not null, reservation_date date not null, start_time time(0) not null, date_analysis timestamp(6), date_create timestamp(6) not null, id_room bigint not null, reservation_type varchar(30) not null check ((reservation_type in ('FLEET_VEHICLE','AUDITORIUM','MEETING_ROOM'))), status varchar(30) not null check ((status in ('ENVIADA_PARA_ANALISE','APROVADA','REPROVADA','CANCELADA','EM_ATENDIMENTO','FINALIZADA'))), user_name_approver varchar(255), user_name_requester varchar(255) not null, observation varchar(1000), reason_failure varchar(255), primary key (id));
create table tbl_room (id bigint generated by default as identity, floor varchar(50) not null, primary key (id));
create table tbl_user (id bigint generated by default as identity, "email" varchar(255) not null unique, img varchar(255), primary key (id));
alter table if exists tbl_fleet_vehicles add constraint fk_fleet_vehicles_driver foreign key (id_driver) references tbl_driver;
alter table if exists tbl_meeting_room add constraint fk_meeting_room_room foreign key (id_room) references tbl_room;
